sys_script.script:
(function executeRule(current, previous /*null when async*/) {
    if (current.assigned_department) {
        var dept = new GlideRecord("cmn_department");
        if (dept.get(current.assigned_department)) {
            if (dept.dept_head) {
                current.assigned_to = dept.dept_head; 
            }
        }
    }
})(current, previous);
